package com.jobmatching.demo.security;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Fixtures below were generated by the actual Werkzeug installation used by JobSpy-main
 * (werkzeug 3.1.8) via:
 *   generate_password_hash('CorrectHorse123', method=...)
 * They pin down the exact wire format this encoder must interoperate with.
 */
class WerkzeugPasswordEncoderTest {

    private final WerkzeugPasswordEncoder encoder = new WerkzeugPasswordEncoder();

    @Test
    void verifiesRealWerkzeugScryptHash_defaultParams() {
        String hash = "scrypt:32768:8:1$EiBrsNR2Vrf5fQeD$8861e63f46989584618460807fb837f24700c2796cc81a1427b410b9bfa8ea1f7dcb1c114ef2af4e2e4267e3a0be5eb0354fe139b33ab9d445e94fa3d41bd142";
        assertTrue(encoder.matches("CorrectHorse123", hash));
        assertFalse(encoder.matches("WrongPassword", hash));
    }

    @Test
    void verifiesRealWerkzeugScryptHash_customParams() {
        String hash = "scrypt:16384:8:1$DNyx8glVagXRjE3J$74dc614e698965d1f7bf6a450aa5db1e28cfe8d75656b16407fc1914df23d8fd60ebfafba8b990d2e830d818e7fcb7c35175ce670bb8b70347462c0105e17bd4";
        assertTrue(encoder.matches("CorrectHorse123", hash));
    }

    @Test
    void verifiesRealWerkzeugPbkdf2Hash() {
        String hash = "pbkdf2:sha256:600000$bXbJIY3BRT1FnLge$181bb3a3f3ff7cda9db349c416f807343ba325e95b3e40fda4d5135aa4a21e06";
        assertTrue(encoder.matches("CorrectHorse123", hash));
        assertFalse(encoder.matches("WrongPassword", hash));
    }

    @Test
    void encodeThenMatchesRoundTrips() {
        String encoded = encoder.encode("SomeNewPassword1");
        assertTrue(encoded.startsWith("scrypt:32768:8:1$"));
        assertTrue(encoder.matches("SomeNewPassword1", encoded));
        assertFalse(encoder.matches("SomeOtherPassword", encoded));
    }
}
